cd /workspace/probe/corpus && node -e "
const {execFileSync}=require('child_process');const fs=require('fs');
const files=fs.readdirSync('collections-block').sort();
let ok=0,err=0,argparse=0;const bad=[];
for(const f of files){
  const buf=fs.readFileSync('collections-block/'+f,'utf8');
  let out,rc=0;
  try{ out=execFileSync('/workspace/dataset/test14_executable',['--a',buf],{encoding:'utf8',stdio:['ignore','pipe','pipe']}); }
  catch(e){ rc=e.status; out=(e.stdout||'')+(e.stderr||''); }
  if(rc===0) ok++; else { err++; if(/unrecognized arguments|expected one argument|usage:/.test(out)) {argparse++; bad.push(f+' ARGPARSE');} }
}
console.log('total',files.length,'rc0',ok,'rc!=0',err,'argparse-eaten',argparse);
console.log(bad.join('\n'));
"

